static <T> T executeInTransaction(SessionFactory sf, Function<Session, T> logic) {
    try (Session s = sf.openSession()) {
        Transaction tx = s.beginTransaction();
        T result = logic.apply(s);
        tx.commit();
        return result;
    }
}

